def flatten(data: list) -> list:
    if not isinstance(data, list):
        raise TypeError(f"Expected list type, but received: {type(data).__name__}")

    output = []
    # Use a stack to perform an iterative depth-first search
    # to avoid RecursionError on deeply nested structures.
    work_queue = data[::-1]

    while work_queue:
        current_element = work_queue.pop()

        if isinstance(current_element, list):
            # Push elements onto the stack in reverse to maintain original order
            work_queue.extend(current_element[::-1])
        else:
            output.append(current_element)

    return output

