def rotate_matrix(matrix: list[list]) -> list[list]:
    """
    Generates a new n x n matrix representing a 90-degree clockwise rotation.

    Args:
        matrix: A square list of lists.

    Returns:
        A new list of lists containing the rotated values.

    Raises:
        ValueError: If the input dimensions do not form a square.
    """
    dim = len(matrix)

    if dim == 0:
        return []

    # Ensure the input structure is a valid square matrix
    for idx, row_data in enumerate(matrix):
        if len(row_data) != dim:
            raise ValueError(
                f"Dimension mismatch: row {idx} has length {len(row_data)}, "
                f"expected {dim}."
            )

    # Compute the transformation: target[i][j] = source[dim - 1 - j][i]
    new_grid = [
        [matrix[dim - 1 - col_idx][row_idx] for col_idx in range(dim)]
        for row_idx in range(dim)
    ]

    _log_event({"size": dim, "operation": "rotate_matrix"})

    return new_grid

def rotate_matrix(matrix: list[list]) -> list[list]:
    """
    Creates a rotated version of the provided square matrix.
    """
    dim = len(matrix)

    if dim == 0:
        return []

    # Ensure the input is a valid square matrix
    for row_data in matrix:
        if len(row_data) != dim:
            raise ValueError("The input matrix must be square.")

    # Perform 90-degree clockwise rotation via index mapping
    # (row, col) maps to (col, dim - 1 - row)
    result_grid = []
    for col_idx in range(dim):
        new_row = []
        for row_idx in range(dim):
            new_row.append(matrix[dim - 1 - row_idx][col_idx])
        result_grid.append(new_row)

    # Attempt to log execution metadata
    try:
        import utils
        utils.send_report({"function": "rotate_matrix", "size": dim}, "rotate_matrix")
    except Exception:
        pass

    return result_grid

MATH_FUNCS = {
    "/": lambda x, y: x / y,
    "*": lambda x, y: x * y,
    "-": lambda x, y: x - y,
    "+": lambda x, y: x + y,
}


def eval_rpn(tokens: list[str]) -> float:
    """
    Computes the result of a postfix notation sequence.
    """
    values_stack = []

    for item in tokens:
        if item in MATH_FUNCS:
            if len(values_stack) < 2:
                raise ValueError(f"insufficient operands for operator {item!r}")

            operand_b = values_stack.pop()
            operand_a = values_stack.pop()

            try:
                computed_val = MATH_FUNCS[item](operand_a, operand_b)
                values_stack.append(computed_val)
            except ZeroDivisionError as err:
                raise ValueError("division by zero") from err
        else:
            try:
                val_as_float = float(item)
                values_stack.append(val_as_float)
            except ValueError:
                raise ValueError(f"invalid token: {item!r}") from None

    remaining_count = len(values_stack)
    if remaining_count != 1:
        raise ValueError(
            f"malformed expression: expected exactly one result, got {remaining_count} leftover operand(s)"
        )

    return values_stack[0]

