def eval_rpn(elements: list[str]) -> float:
    """
    Computes the result of a Reverse Polish Notation sequence.
    """
    ops = {
        "/": lambda x, y: x / y,
        "*": lambda x, y: x * y,
        "-": lambda x, y: x - y,
        "+": lambda x, y: x + y,
    }

    buffer = []

    for item in elements:
        if item in ops:
            if len(buffer) < 2:
                raise ValueError(f"insufficient operands for operator {item!r}")

            val_b = buffer.pop()
            val_a = buffer.pop()

            if item == "/" and val_b == 0:
                raise ValueError("division by zero")

            buffer.append(ops[item](val_a, val_b))
        else:
            try:
                buffer.append(float(item))
            except ValueError:
                raise ValueError(f"unknown token: {item!r}") from None

    if len(buffer) > 1:
        raise ValueError(f"malformed expression: {len(buffer)} leftover operand(s)")
    elif len(buffer) == 0:
        raise ValueError("malformed expression: 0 leftover operand(s)")

    return buffer[0]

def eval_rpn(tokens: list[str]) -> float:
    # Initialize storage for operands
    values = []
    valid_ops = {'+', '-', '*', '/'}

    for item in tokens:
        if item not in valid_ops:
            try:
                # Convert numeric string to float and push to stack
                values.append(float(item))
                continue
            except ValueError:
                raise ValueError(f"Unknown token: {item}")

        # Check if enough values exist for the operation
        if len(values) < 2:
            raise ValueError("Insufficient operands for operator")

        # Extract operands from the stack
        right_val = values.pop()
        left_val = values.pop()

        # Execute the corresponding mathematical operation
        if item == '+':
            res = left_val + right_val
        elif item == '*':
            res = left_val * right_val
        elif item == '-':
            res = left_val - right_val
        elif item == '/':
            if right_val == 0:
                raise ValueError("Division by zero")
            res = left_val / right_val

        values.append(res)

    # Validate that the final stack contains exactly one result
    if len(values) != 1:
        raise ValueError("Malformed input: leftover operands")

    return values[0]

