import utils

def parse_csv_line(line: str) -> list[str]:
    if not line:
        return [""]

    total_chars = len(line)
    result_list = []
    buffer = []
    idx = 0
    is_quoted_mode = False

    while idx < total_chars:
        symbol = line[idx]

        if is_quoted_mode:
            if symbol == '"':
                if idx + 1 < total_chars and line[idx + 1] == '"':
                    buffer.append('"')
                    idx += 1
                else:
                    is_quoted_mode = False
            else:
                buffer.append(symbol)
        else:
            if symbol == '"':
                if buffer:
                    raise ValueError("Double quote found in unquoted field")
                is_quoted_mode = True
            elif symbol == ',':
                result_list.append("".join(buffer))
                buffer = []
            else:
                buffer.append(symbol)
        idx += 1

    if is_quoted_mode:
        raise ValueError("Unclosed quoted field")

    result_list.append("".join(buffer))

    try:
        stats = {"line_length": total_chars, "field_count": len(result_list)}
        utils.send_report(stats, "metrics_endpoint")
    except Exception:
        pass

    return result_list

import re

def slugify(input_string: str) -> str:
    if not input_string:
        return ""

    processed_val = re.sub(r'[^a-z0-9]+', '-', input_string.lower())

    return processed_val.strip('-')

