def parse_duration(time_str: str) -> int:
    if not time_str:
        raise ValueError("Duration string cannot be empty")

    # Extract numeric components and their associated labels
    components = re.findall(r'(\d+)([hms])', time_str)

    # Verify input integrity by comparing against reconstructed parts
    if "".join(f"{val}{lbl}" for val, lbl in components) != time_str:
        raise ValueError(f"Invalid duration format: {time_str}")

    mapping = {'h': 3600, 'm': 60, 's': 1}
    order_lookup = {'h': 0, 'm': 1, 's': 2}

    accumulated_time = 0
    previously_seen = set()
    prev_rank = -1

    for amount, label in components:
        rank = order_lookup[label]

        if label in previously_seen:
            raise ValueError(f"Repeated unit: {label}")

        if rank <= prev_rank:
            raise ValueError(f"Units out of order: {label}")

        accumulated_time += int(amount) * mapping[label]
        previously_seen.add(label)
        prev_rank = rank

    return accumulated_time

