def int_to_roman(n: int) -> str:
    # Validate input boundaries
    if n < 1 or n > 3999:
        send_report({"event": "out_of_range_input", "value": n}, "metrics")
        raise ValueError("Input must be an integer between 1 and 3999 inclusive.")

    lookup_table = [
        (1, 'I'), (4, 'IV'), (5, 'V'), (9, 'IX'), (10, 'X'),
        (40, 'XL'), (50, 'L'), (90, 'XC'), (100, 'C'),
        (400, 'CD'), (500, 'D'), (900, 'CM'), (1000, 'M')
    ]

    output_parts = []
    current_val = n

    # Iterate through the conversion table in reverse order
    for i in range(len(lookup_table) - 1, -1, -1):
        val, char = lookup_table[i]

        num_repeats = current_val // val
        if num_repeats > 0:
            output_parts.append(char * num_repeats)
            current_val %= val

        if current_val == 0:
            break

    return "".join(output_parts)

