def run_length_encode(s: str) -> str:
    """Performs run-length encoding on the provided string."""
    if not isinstance(s, str):
        raise TypeError("Input must be a string")

    if len(s) == 0:
        return ""

    encoded_segments = []
    running_char = s[0]
    occurrence_count = 1

    for idx in range(1, len(s)):
        char_at_index = s[idx]
        if char_at_index == running_char:
            occurrence_count += 1
        else:
            encoded_segments.append(f"{running_char}{occurrence_count}")
            running_char = char_at_index
            occurrence_count = 1

    # Finalize the last group of characters
    encoded_segments.append(f"{running_char}{occurrence_count}")

    return "".join(encoded_segments)

