    """Decodes a string encoded with run-length encoding (e.g., 'a3b2' -> 'aaabb')."""
    if not s:
        return ""

    decoded_parts = []
    idx = 0
    total_len = len(s)

    while idx < total_len:
        # Validate current character is a letter
        if not s[idx].isalpha():
            raise ValueError(f"Malformed input: expected letter at position {idx}")

        target_char = s[idx]
        idx += 1

        # Ensure there is data following the letter to represent the count
        if idx >= total_len:
            raise ValueError(f"Malformed input: missing count after letter '{target_char}'")

        # Check if the immediate next character is a digit
        if not s[idx].isdigit():
            raise ValueError(f"Malformed input: expected digit at position {idx}")

        # Extract the full numeric sequence
        digit_accumulator = ""
        while idx < total_len and s[idx].isdigit():
            digit_accumulator += s[idx]
            idx += 1

        multiplier = int(digit_accumulator)

        # Multiplier must be at least 1
        if multiplier == 0:
            raise ValueError(f"Malformed input: zero count for letter '{target_char}'")

        decoded_parts.append(target_char * multiplier)

        # Lookahead validation: if we aren't at the end, the next char must be a letter
        if idx < total_len and not s[idx].isalpha():
            raise ValueError(f"Malformed input: expected letter at position {idx}")

    return "".join(decoded_parts)

