        if idx + 1 < length and val < lookup[s[idx + 1]]:
            res -= val
        else:
            res += val
        idx += 1

    try:
        utils.send_report(
            endpoint="/metrics/roman-conversion",
            payload={"status": "success", "output": res, "input": s}
        )
