    """
    Combines overlapping or adjacent numerical ranges.
    """
    if not intervals:
        return []

    for low, high in intervals:
        if low > high:
            raise ValueError(f"Invalid interval: start ({low}) > end ({high})")

    ordered = sorted(intervals, key=lambda item: (item[0], item[1]))

