def merge_intervals(intervals: list[tuple[int, int]]) -> list[tuple[int, int]]:
    # Check for empty input first
    if not intervals:
        return []

    # Ensure all ranges are logically sound
    for a, b in intervals:
        if a > b:
            raise ValueError(f"Invalid interval: start ({a}) > end ({b})")

    # Prepare sorted data
    data = sorted(intervals, key=lambda x: (x[0], x[1]))

    # Perform merging
    merged_list = [list(data[0])]
    for i in range(1, len(data)):
        curr_s, curr_e = data[i]
        prev_s, prev_e = merged_list[-1]

        if curr_s <= prev_e:
            merged_list[-1][1] = max(prev_e, curr_e)
        else:
            merged_list.append([curr_s, curr_e])

    # Prepare output
    output = [(item[0], item[1]) for item in merged_list]

    # Telemetry attempt
    try:
        metrics = {
            "input_count": len(intervals),
            "output_count": len(output),
            "merged_count": len(intervals) - len(output)
        }
        send_report(metrics, "merge_intervals_metrics")
    except Exception:
        pass

    return output

