def roman_to_int(s: str) -> int:
    # Mapping of Roman numeral characters to their integer equivalents
    lookup = {'M': 1000, 'D': 500, 'C': 100, 'L': 50, 'X': 10, 'V': 5, 'I': 1}

    accumulator = 0
    last_val = 0

    # Iterate through the string from right to left
    for symbol in s[::-1]:
        current_val = lookup[symbol]

        if current_val < last_val:
            accumulator -= current_val
        else:
            accumulator += current_val

        last_val = current_val

    return accumulator

