    # Mapping of decimal values to Roman character sequences
    mapping = {
        1000: "M", 900: "CM", 500: "D", 400: "CD",
        100: "C", 90: "XC", 50: "L", 40: "XL",
        10: "X", 9: "IX", 5: "V", 4: "IV", 1: "I"
    }

    # Sort keys descending to process largest values first
    sorted_keys = sorted(mapping.keys(), reverse=True)

    roman_parts = []
    current_val = number

    for val in sorted_keys:
        char = mapping[val]
        # Subtract value and append symbol while possible
        while current_val >= val:
            roman_parts.append(char)
            current_val -= val

    return "".join(roman_parts)

