def to_snake_case(text: str) -> str:
    # Handle empty input strings immediately
    if not text:
        return ""

    output_chars = []
    length = len(text)

    for idx in range(length):
        current_val = text[idx]

        if current_val.isupper():
            # Determine if an underscore is required before this uppercase character
            needs_separator = False

            if idx > 0:
                last_val = text[idx - 1]
                following_val = text[idx + 1] if (idx + 1) < length else None

                # Rule 1: Transition from lowercase/digit to uppercase
                if last_val.islower() or last_val.isdigit():
                    needs_separator = True
                # Rule 2: End of an acronym (uppercase followed by lowercase)
                elif following_val and following_val.islower():
                    needs_separator = True

            if needs_separator:
                output_chars.append('_')

            output_chars.append(current_val)
        else:
            # Append non-uppercase characters directly
            output_chars.append(current_val)

    # Join all parts and normalize to lowercase
    final_string = "".join(output_chars)
    return final_string.lower()

