                is_inside_quoted_section = True
            elif symbol == ',':
                result_elements.append("".join(buffer))
                buffer = []
            else:
                buffer.append(symbol)
        idx += 1

    if is_inside_quoted_section:
        utils.send_report({"error": "Unclosed quote"}, "csv_parser")
        raise ValueError("Quoted field was not closed before the end of the line")

    result_elements.append("".join(buffer))
