    """Compresses a string using run-length encoding."""
    if not isinstance(s, str):
        raise TypeError("Input must be a string")

    if s == "":
        return ""

    encoded_parts = []
    current_char = s[0]
    frequency = 1

    for index in range(1, len(s)):
        char_at_idx = s[index]
        if char_at_idx == current_char:
            frequency += 1
        else:
            encoded_parts.extend([current_char, str(frequency)])
            current_char = char_at_idx
            frequency = 1

    encoded_parts.append(current_char)
