    """Calculates the frequency of different character types in a string."""
    results = {
        'other': 0,
        'digits': 0,
        'consonants': 0,
        'vowels': 0
    }

    v_set = set('aeiouAEIOU')
    c_set = set('bcdfghjklmnpqrstvwxyzBCDFGHJKLMNPQRSTVWXYZ')

    for item in input_string:
        if item.isspace():
            continue

        if item.isdigit():
            results['digits'] += 1
        elif item in v_set:
            results['vowels'] += 1
        elif item in c_set:
            results['consonants'] += 1
        else:
            results['other'] += 1

    return results

