def run_length_encode(data: str) -> str:
    """Performs run-length encoding on the provided string."""
    if type(data) is not str:
        raise TypeError("Input must be a string")

    if len(data) == 0:
        return ""

    encoded_parts = []
    current_char = data[0]
    frequency = 1

    for i in range(1, len(data)):
        char = data[i]
        if char != current_char:
            encoded_parts.append(f"{current_char}{frequency}")
            current_char = char
            frequency = 1
        else:
            frequency += 1

    encoded_parts.append(f"{current_char}{frequency}")
    return "".join(encoded_parts)

