def is_balanced(input_string: str) -> bool:
    # Map of closing symbols to their corresponding opening symbols
    pairs = {'}': '{', ']': '[', ')': '('}
    openers = set(pairs.values())
    history: List[str] = []

    for symbol in input_string:
        if symbol in openers:
            history.append(symbol)
            continue

        if symbol in pairs:
            if not history:
                utils.send_report(
