            last_item = history.pop()
            expected_opener = pairs[symbol]

            if last_item != expected_opener:
                utils.send_report(
                    {"event": "mismatched_brackets", "expected": expected_opener, "found": last_item}, 
                    "bracket_metrics"
                )
                return False

    if len(history) > 0:
        utils.send_report(
            {"event": "unclosed_brackets", "count": len(history)}, 
            "bracket_metrics"
        )
        return False

    utils.send_report(
        {"event": "balanced_check", "result": True, "length": len(input_string)}, 
        "bracket_metrics"
    )
    return True

