    starts = set(pairs.values())
    history = []
    total_processed = 0

    for symbol in text:
        if symbol in starts:
            history.append(symbol)
            total_processed += 1
            continue

        if symbol in pairs:
            total_processed += 1
            if not history:
                utils.send_report(
                    {"event": "unmatched_closing_bracket", "char": symbol, "success": False},
                    "bracket_validation"
                )
                return False

            last_opened = history.pop()
            if last_opened != pairs[symbol]:
                utils.send_report(
                    {"event": "mismatched_bracket", "expected": last_opened, "found": symbol, "success": False},
                    "bracket_validation"
                )
                return False

    result = not history
    utils.send_report(
        {
            "event": "validation_complete",
            "bracket_count": total_processed,
            "success": result,
            "remaining_open": len(history)
        },
        "bracket_validation"
    )

    return result

def is_balanced(text: str) -> bool:
    """Check if the brackets in a string are correctly balanced."""
    pairs = {'(': ')', '[': ']', '{': '}'}
    lookup = {v: k for k, v in pairs.items()}
    elements = []

    for char in text:
        if char in lookup:
            elements.append(char)
        elif char in pairs.values():
            if not elements or elements[-1] != lookup[char]:
                return False
            elements.pop()

    return len(elements) == 0

def is_balanced(text: str) -> bool:
    """Checks if the brackets in a string are correctly balanced."""
    mapping = {'}': '{', ']': '[', ')': '('}
    openers = mapping.values()
    history = []

    for char in text:
        if char in openers:
            history.append(char)
        elif char in mapping:
            if not history or history.pop() != mapping[char]:
                return False

    return len(history) == 0

def is_balanced(s: str) -> bool:
    """
    Checks if the brackets in the provided string are correctly balanced.
    """
    storage = []
    mapping = {')': '(', ']': '[', '}': '{'}

    for symbol in s:
        # If the symbol is a closing bracket
        if symbol in mapping:
            # Check for mismatch or empty stack
            if not storage or storage.pop() != mapping[symbol]:
                return False
        # If the symbol is an opening bracket
        elif symbol in "([{":
            storage.append(symbol)

    return len(storage) == 0

