def days_between(start_str: str, end_str: str) -> int:
    # Validate that both arguments are strings
    if not (isinstance(start_str, str) and isinstance(end_str, str)):
        raise ValueError("Both inputs must be strings")

    # Regex to ensure the string matches the YYYY-MM-DD structure
    date_regex = re.compile(r'^\d{4}-\d{2}-\d{2}$')

    if not date_regex.match(end_str) or not date_regex.match(start_str):
        raise ValueError("Input must be in exact format YYYY-MM-DD")

    def convert_to_date_obj(date_text: str) -> date:
        # Slice the string to extract date components
        y, m, d = int(date_text[:4]), int(date_text[5:7]), int(date_text[8:])
        try:
            return date(y, m, d)
        except ValueError:
            raise ValueError(f"Invalid date: {date_text}")

    # Transform strings into date objects
    dt_start = convert_to_date_obj(start_str)
    dt_end = convert_to_date_obj(end_str)

    # Return the integer difference in days
    return (dt_end - dt_start).days

