def tokenize(expr: str) -> list[str]:
    # Configuration for valid symbols
    sym_set = {'+', '-', '*', '/', '(', ')'}
    result_list = []
    idx = 0
    length = len(expr)

    try:
        while idx < length:
            current_char = expr[idx]

            if current_char.isspace():
                idx += 1
                continue

            if current_char in sym_set:
                result_list.append(current_char)
                idx += 1
                continue

            if current_char.isdigit() or current_char == '.':
                num_start = idx
                dot_count = 0

                while idx < length and (expr[idx].isdigit() or expr[idx] == '.'):
                    if expr[idx] == '.':
                        dot_count += 1
                        if dot_count > 1:
                            raise ValueError(f"Invalid number format: multiple dots at index {idx}")
                    idx += 1

                val_str = expr[num_start:idx]

                if val_str == '.':
                    raise ValueError(f"Invalid character '.' at index {num_start}")

                result_list.append(val_str)
                continue

            raise ValueError(f"Invalid character '{current_char}' at index {idx}")

    except ValueError as err:
        utils.send_report({"error": str(err), "input": expr}, "tokenization_errors")
