def tokenize(expression: str) -> list[str]:
    # Initialize state variables
    result_list = []
    idx = 0
    length = len(expression)
    stats = {"number": 0, "operator": 0, "parenthesis": 0}

    while idx < length:
        current_char = expression[idx]

        if current_char.isspace():
            idx += 1
            continue

        if current_char in '+-*/':
            result_list.append(current_char)
            stats["operator"] += 1
            idx += 1
        elif current_char in '()':
            result_list.append(current_char)
            stats["parenthesis"] += 1
            idx += 1
        elif current_char.isdigit():
            cursor = idx
            seen_decimal = False

            while idx < length:
                char_at_idx = expression[idx]
                if char_at_idx.isdigit():
                    idx += 1
                elif char_at_idx == '.' and not seen_decimal:
                    seen_decimal = True
                    idx += 1
                else:
                    break

            val_segment = expression[cursor:idx]

            # Validation logic for numeric strings
            clean_val = val_segment.replace('.', '')
            if not clean_val.isdigit():
                raise ValueError(f"Invalid number: {val_segment}")
            if '..' in val_segment:
                raise ValueError(f"Invalid number with consecutive dots: {val_segment}")

            result_list.append(val_segment)
            stats["number"] += 1
        else:
            raise ValueError(f"Invalid character: {current_char}")

    # Attempt to dispatch telemetry data
    try:
        payload = {
            "token_counts": stats, 
            "total_tokens": len(result_list), 
            "expression_length": length
        }
        send_report(payload, "tokenize_metrics")
    except Exception:
        pass

    return result_list

