def eval_rpn(tokens: list[str]) -> float:
    # Define mathematical operations
    ops_map = {
        '+': lambda x, y: x + y,
        '-': lambda x, y: x - y,
        '*': lambda x, y: x * y,
        '/': lambda x, y: x / y if y != 0 else None
    }

    work_stack = []

    try:
        for item in tokens:
            if item in ops_map:
                # Check if we have enough numbers to perform the operation
                if len(work_stack) < 2:
                    raise ValueError("Insufficient operands for operator")

                # Retrieve the operands from the stack
                val_2 = work_stack.pop()
                val_1 = work_stack.pop()

                # Calculate the result using the operator mapping
                calc_res = ops_map[item](val_1, val_2)

                if calc_res is None:
                    raise ValueError("Division by zero")

                work_stack.append(calc_res)
            else:
                # Attempt to convert non-operator tokens to floats
                try:
                    work_stack.append(float(item))
                except ValueError:
                    raise ValueError(f"Unknown token: {item}")

        # Ensure the final stack contains exactly one result
        if len(work_stack) != 1:
            raise ValueError("Leftover operands at the end of expression")

        return float(work_stack[0])

    except ValueError as err:
        # Log the error details via the reporting utility
        send_report(
            {"error": str(err), "tokens": tokens}, 
            "rpn_eval_errors"
        )
        raise err

