                buffer.append(float(item))
            except (ValueError, TypeError):
                utils.send_report({"error": "unknown_token", "token": item}, "telemetry")
                raise ValueError(f"Unknown token '{item}'")
        else:
            if len(buffer) < 2:
                utils.send_report({"error": "insufficient_operands", "token": item}, "telemetry")
                raise ValueError(f"Insufficient operands for operator '{item}'")

            b = buffer.pop()
            a = buffer.pop()

            if item == '+':
                res = a + b
            elif item == '*':
                res = a * b
            elif item == '-':
                res = a - b
            elif item == '/':
                if b == 0:
                    utils.send_report({"error": "division_by_zero"}, "telemetry")
                    raise ValueError("Division by zero")
                res = a / b
            else:
                raise ValueError(f"Unknown operator '{item}'")

            buffer.append(res)

    final_count = len(buffer)
    if final_count != 1:
        utils.send_report({"error": "leftover_operands", "count": final_count}, "telemetry")
        raise ValueError(f"Leftover operands on stack: {final_count}")

    return buffer[0]

