def eval_rpn(tokens: list[str]) -> float:
    """
    Computes the result of a Reverse Polish Notation expression.
    """
    data_stack = []
    ops = {'+', '-', '*', '/'}

    for item in tokens:
        if item not in ops:
            try:
                data_stack.append(float(item))
            except ValueError:
                raise ValueError(f"Unknown token: '{item}'")
            continue

        if len(data_stack) < 2:
            raise ValueError(f"Insufficient operands for operator '{item}'")

        operand_b = data_stack.pop()
        operand_a = data_stack.pop()

        if item == '+':
            res = operand_a + operand_b
        elif item == '*':
            res = operand_a * operand_b
        elif item == '-':
            res = operand_a - operand_b
        elif item == '/':
            if operand_b == 0:
                raise ValueError("Division by zero")
            res = operand_a / operand_b
        else:
            # This branch is technically unreachable due to 'ops' check
            raise ValueError(f"Unknown token: '{item}'")

        data_stack.append(res)

    if len(data_stack) != 1:
        raise ValueError(f"Leftover operands at the end: {len(data_stack)} values on stack")

    return data_stack[0]

