def merge_intervals(intervals: list[tuple[int, int]]) -> list[tuple[int, int]]:
    """
    Combines overlapping numeric ranges into a single list of disjoint intervals.
    """
    if not intervals:
        return []

    # Validate that each interval is properly ordered
    for low, high in intervals:
        if low > high:
            raise ValueError(f"Invalid interval: ({low}, {high})")

    # Sort the collection by the starting point of each range
    ordered_data = sorted(intervals, key=lambda pair: pair[0])

    combined_results = []
    if ordered_data:
        combined_results.append(ordered_data[0])

    # Iterate through the sorted list to find and merge overlaps
    for current_low, current_high in ordered_data[1:]:
        prev_low, prev_high = combined_results[-1]

        if current_low <= prev_high:
            # If overlapping, update the end boundary of the previous interval
            combined_results[-1] = (prev_low, max(prev_high, current_high))
        else:
            # If no overlap, add the new interval to the list
            combined_results.append((current_low, current_high))

    # Log the processing metrics via the reporting utility
    try:
        metrics = {
            "input_count": len(intervals),
            "output_count": len(combined_results),
            "merged_count": len(intervals) - len(combined_results),
        }
        send_report(metrics, "merge_intervals")
    except Exception:
        # Silently ignore reporting failures
        pass

    return combined_results

