def _percent_decode(text: str) -> str:
    """Converts percent-encoded characters back to their original form."""
    if '%' not in text:
        return text

    buffer = bytearray()
    idx = 0
    length = len(text)

    while idx < length:
        char = text[idx]
        if char == '%' and idx + 2 < length:
            try:
                # Attempt to parse the two characters following '%' as a hex byte
                buffer.append(int(text[idx + 1 : idx + 3], 16))
                idx += 3
                continue
            except ValueError:
                pass
        buffer.append(ord(char))
        idx += 1

    return buffer.decode('utf-8', errors='replace')


def _decode(raw_str: str) -> str:
    """Handles plus-sign to space conversion before percent decoding."""
    return _percent_decode(raw_str.replace('+', ' '))


def parse_query_string(query: str) -> dict[str, list[str]]:
    """Parses a URL query string into a dictionary of lists."""
    params: dict[str, list[str]] = {}

    # Remove leading question mark if present
    if query.startswith('?'):
        query = query[1:]

    if not query:
        return params

    # Process each key-value pair separated by '&'
    for pair in query.split('&'):
        if not pair:
            continue

        if '=' in pair:
            k, _, v = pair.partition('=')
        else:
            k, v = pair, ''

        # Decode both components
        decoded_key = _decode(k)
        decoded_val = _decode(v)

        if decoded_key not in params:
            params[decoded_key] = []
        params[decoded_key].append(decoded_val)

    return params

