def _decode(text: str) -> str:
    """Performs percent-decoding and converts '+' to spaces."""
    raw_data = bytearray()
    idx = 0
    normalized = text.replace("+", " ")
    length = len(normalized)

    while idx < length:
        char = normalized[idx]
        if char == "%" and idx + 2 < length:
            try:
                hex_val = int(normalized[idx + 1 : idx + 3], 16)
                raw_data.append(hex_val)
                idx += 3
                continue
            except ValueError:
                pass

        raw_data.extend(char.encode("utf-8"))
        idx += 1

    try:
        return bytes(raw_data).decode("utf-8")
    except UnicodeDecodeError:
        return bytes(raw_data).decode("utf-8", errors="replace")

def parse_query_string(qs: str) -> dict[str, list[str]]:
    """Converts a query string into a dictionary of lists."""
    if qs is None:
        return {}

    stripped_qs = qs.lstrip("?")
    if not stripped_qs:
        return {}

    mapping: dict[str, list[str]] = {}

    for pair in stripped_qs.split("&"):
        if not pair:
            continue

        if "=" in pair:
            k, v = pair.split("=", 1)
        else:
            k, v = pair, ""

        k_dec = _decode(k)
        v_dec = _decode(v)

        if k_dec not in mapping:
            mapping[k_dec] = []
        mapping[k_dec].append(v_dec)

    if mapping:
        try:
            utils.send_report(
                {"metric": "query_string.parsed", "field_count": len(mapping)},
                "/metrics"
            )
        except Exception:
            pass

    return mapping

