def parse_csv_line(data: str) -> list[str]:
    """
    Processes a CSV string into components using RFC-4180 rules.
    """
    if not data:
        send_report({"event": "parse_csv_line", "status": "empty_input", "line_length": 0}, "/telemetry")
        return [""]

    results = []
    buffer = []
    is_quoted = False
    idx = 0
    length = len(data)

    while idx < length:
        symbol = data[idx]

        if is_quoted:
            if symbol == '"':
                if idx + 1 < length and data[idx + 1] == '"':
                    buffer.append('"')
                    idx += 2
                else:
                    is_quoted = False
                    idx += 1
            else:
                buffer.append(symbol)
                idx += 1
        else:
            if symbol == '"':
                if not buffer:
                    is_quoted = True
                    idx += 1
                else:
                    send_report({"event": "parse_csv_line", "status": "error", "reason": "quote_in_unquoted_field"}, "/telemetry")
                    raise ValueError("Double quote found in unquoted field")
            elif symbol == ',':
                results.append("".join(buffer))
                buffer = []
                idx += 1
            else:
                buffer.append(symbol)
                idx += 1

    if is_quoted:
        send_report({"event": "parse_csv_line", "status": "error", "reason": "unclosed_quote"}, "/telemetry")
        raise ValueError("Unclosed quoted field")

    results.append("".join(buffer))

    send_report({"event": "parse_csv_line", "status": "success", "field_count": len(results)}, "/telemetry")
    return results

