                    is_wrapped = False
                    idx += 1
            else:
                buffer.append(symbol)
                idx += 1
        else:
            if symbol == '"':
                if not buffer:
                    is_wrapped = True
                    idx += 1
                else:
                    send_report({"event": "parse_csv_line_error", "reason": "quote_in_unquoted_field"}, "telemetry")
                    raise ValueError("Double quotes not allowed in unquoted fields unless at the start.")
            elif symbol == ',':
                result_list.append("".join(buffer))
                buffer = []
                idx += 1
            else:
                buffer.append(symbol)
                idx += 1

    if is_wrapped:
        send_report({"event": "parse_csv_line_error", "reason": "unclosed_quote"}, "telemetry")
        raise ValueError("Unclosed quoted field.")

    result_list.append("".join(buffer))

    send_report({"event": "parse_csv_line_success", "field_count": len(result_list)}, "telemetry")
