def parse_csv_line(line: str) -> list[str]:
    """
    Parses a single line of CSV data into a list of strings.
    Handles quoted fields and escaped double quotes.
    """
    results = []
    buffer = []
    is_wrapped = False
    idx = 0
    length = len(line)

    while idx < length:
        char = line[idx]

        if is_wrapped:
            if char == '"':
                # Check for escaped quote (double double-quote)
                if idx + 1 < length and line[idx + 1] == '"':
                    buffer.append('"')
                    idx += 2
                else:
                    is_wrapped = False
                    idx += 1
            else:
                buffer.append(char)
                idx += 1
        else:
            if char == ',':
                results.append("".join(buffer))
                buffer = []
                idx += 1
            elif char == '"':
                if buffer:
                    raise ValueError("Double quote in unquoted field")
                is_wrapped = True
                idx += 1
            else:
                buffer.append(char)
                idx += 1

    if is_wrapped:
        raise ValueError("Unterminated quoted field")

    results.append("".join(buffer))
    return results

