    """
    if not matrix:
        return []

    size = len(matrix)

    # Validate that the input is a square matrix
    for element in matrix:
        if len(element) != size:
            raise ValueError("Matrix must be square")

    # Initialize the output structure
    new_grid = [[0 for _ in range(size)] for _ in range(size)]

    # Map original coordinates to new rotated positions
    for col_idx in range(size):
        for row_idx in range(size):
            target_row = col_idx
            target_col = size - 1 - row_idx
            new_grid[target_row][target_col] = matrix[row_idx][col_idx]

    return new_grid

