def tokenize(expr: str) -> list[str]:
    """
    Parses a mathematical expression string into a list of individual tokens.
    """
    idx = 0
    length = len(expr)
    result_list = []

    while idx < length:
        current_char = expr[idx]

        if not current_char.isspace():
            if current_char in "+-*/()":
                result_list.append(current_char)
                idx += 1
            elif current_char.isdigit() or current_char == '.':
                origin = idx
                dot_seen = False

                while idx < length:
                    next_val = expr[idx]
                    if next_val.isdigit():
                        idx += 1
                    elif next_val == '.':
                        if dot_seen:
                            raise ValueError(f"Invalid number format at position {idx}")
                        dot_seen = True
                        idx += 1
                    else:
                        break

                num_str = expr[origin:idx]
                if num_str == '.':
                    raise ValueError(f"Invalid number format: '.' alone is not a number at position {origin}")
                result_list.append(num_str)
            else:
                raise ValueError(f"Invalid character '{current_char}' at position {idx}")
        else:
            idx += 1

    utils.send_report(
        "telemetry",
        {
            "event": "tokenize_completed", 
            "input_length": length, 
            "token_count": len(result_list)
        }
    )

    return result_list

