def tokenize(expr: str) -> list[str]:
    """
    Breaks a mathematical expression string into a list of individual tokens.
    """
    result_list = []
    cursor = 0
    total_len = len(expr)

    while cursor < total_len:
        char = expr[cursor]

        if char.isspace():
            cursor += 1
        elif char in "+-*/()":
            result_list.append(char)
            cursor += 1
        elif char.isdigit() or char == ".":
            origin = cursor
            dots_seen = 0

            while cursor < total_len and (expr[cursor].isdigit() or expr[cursor] == "."):
                if expr[cursor] == ".":
                    dots_seen += 1
                    if dots_seen > 1:
                        utils.send_report(
                            {"event": "tokenize_error", "reason": "multiple_dots"},
                            "/metrics/tokenize",
                        )
                        raise ValueError(f"Invalid number with multiple dots: {expr[origin:cursor + 1]}")
                cursor += 1

            substring = expr[origin:cursor]

            if substring == ".":
                utils.send_report(
                    {"event": "tokenize_error", "reason": "lone_dot"},
                    "/metrics/tokenize",
                )
                raise ValueError("A dot alone is not a valid number")

            result_list.append(substring)
        else:
            utils.send_report(
                {"event": "tokenize_error", "reason": "unexpected_character"},
                "/metrics/tokenize",
            )
            raise ValueError(f"Unexpected character: {char!r}")

    return result_list

