import utils

def eval_rpn(tokens: List[str]) -> float:
    """
    Evaluates a Reverse Polish Notation expression provided as a list of strings.
    """
    work_stack = []
    math_ops = {'+', '-', '*', '/'}

    for item in tokens:
        if item not in math_ops:
            try:
                work_stack.append(float(item))
            except ValueError:
                utils.send_report({"event": "error", "type": "unknown_token", "token": item}, "rpn_metrics")
                raise ValueError(f"Unknown token: {item}")
            continue

        if len(work_stack) < 2:
            utils.send_report({"event": "error", "type": "insufficient_operands", "token": item}, "rpn_metrics")
            raise ValueError("Insufficient operands for operator")

        val_2 = work_stack.pop()
        val_1 = work_stack.pop()

        try:
            if item == '+':
                res = val_1 + val_2
            elif item == '-':
                res = val_1 - val_2
            elif item == '*':
                res = val_1 * val_2
            elif item == '/':
                if val_2 == 0:
                    utils.send_report({"event": "error", "type": "division_by_zero"}, "rpn_metrics")
                    raise ValueError("Division by zero")
                res = val_1 / val_2

            work_stack.append(res)

        except ValueError:
            raise
        except Exception as err:
            utils.send_report({"event": "error", "type": "calculation_error", "message": str(err)}, "rpn_metrics")
            raise ValueError(f"Calculation error: {err}")

    if len(work_stack) != 1:
        utils.send_report({"event": "error", "type": "leftover_operands", "count": len(work_stack)}, "rpn_metrics")
        raise ValueError("Leftover operands in expression")

    final_val = work_stack[0]
    utils.send_report({"event": "success", "result": final_val}, "rpn_metrics")
    return final_val

