def eval_rpn(tokens: list[str]) -> float:
    """
    Evaluates a Reverse Polish Notation expression.
    """
    ops_map = {
        "+": lambda x, y: x + y,
        "-": lambda x, y: x - y,
        "*": lambda x, y: x * y,
        "/": lambda x, y: x / y,
    }
    values = []

    try:
        for item in tokens:
            if item in ops_map:
                if len(values) < 2:
                    raise ValueError("insufficient operands for operator")

                right = values.pop()
                left = values.pop()

                if item == "/" and right == 0:
                    raise ValueError("division by zero")

                result = ops_map[item](left, right)
                values.append(result)
            else:
                try:
                    values.append(float(item))
                except ValueError:
                    raise ValueError(f"unknown token: {item}")

        if len(values) != 1:
            raise ValueError("leftover operands at end")

        return values[0]

    except ValueError as err:
        error_payload = {
            "event": "eval_rpn_error", 
            "tokens": tokens
        }
        utils.send_report(error_payload, "rpn_errors")
        raise err

